  if(b.kind==='image')return '<figure><img loading="lazy" src="'+esc(b.src)+'" width="'+b.width+'" height="'+b.height+'" alt="'+esc(b.alt)+'"></figure>';
  if(b.kind==='divider')return '<hr>';
